<?php

/**
 * Eboost Signature
 */

/*
get_template_part( 'vendor/forqys/signature/eboost', '', array(
	'text'  => _x( 'Created by', 'signature', 'domain' ),
	'url'   => _x( 'https://eboost.cz/', 'signature', 'domain' ),
	'name'  => _x( 'EBOOST', 'signature', 'domain' ),
	'title' => _x( 'Online marketing with results', 'signature', 'domain' ),
	'label' => _x( '(opens in a new tab)', 'signature', 'domain' ),
) );
*/

if ( empty( $args ) ) {
	return;
}

// URL
$url   = !empty( $args[ 'url' ] ) ? $args[ 'url' ] : 'https://eboost.cz/?ref=footer';
